export const DEBT_INTEREST_RISK_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu pinjaman",q:"'Pinjaman' (utang) adalah...",options:["Uang atau barang yang kamu terima sekarang dari pihak lain dengan janji mengembalikannya nanti, biasanya ditambah bunga","Uang yang diberikan pihak lain sebagai hadiah, tanpa perlu dikembalikan maupun dikenai biaya tambahan di kemudian hari","Uang tabunganmu sendiri yang disimpan di bank dan bisa diambil kapan saja kamu butuh tanpa membayar bunga"],answer:0,explain:"Berutang berarti memakai uang orang lain hari ini & wajib mengembalikannya di kemudian hari, sering kali lebih besar dari yang dipinjam.",hint:"Apakah uang pinjaman harus dikembalikan?"},
{n:2,type:"mcq",micro:"Bunga pinjaman",q:"'Bunga' pada sebuah pinjaman adalah...",options:["Potongan harga yang kamu dapatkan dari penjual karena kamu membeli barang dalam jumlah yang sangat banyak sekaligus","Biaya tambahan yang kamu bayar kepada pemberi pinjaman sebagai 'sewa' atas uang yang kamu pinjam","Hadiah berupa uang tambahan dari bank yang diberikan kepada orang yang mau meminjam uang dalam jumlah besar"],answer:1,explain:"Pemberi pinjaman ingin imbalan karena merelakan uangnya dipakai orang lain & menanggung risiko. Itulah bunga.",hint:"Kamu mengembalikan lebih banyak atau lebih sedikit dari yang dipinjam?"},
{n:3,type:"mcq",micro:"Pokok pinjaman",q:"'Pokok' (principal) sebuah pinjaman adalah...",options:["Biaya tambahan yang dibayar karena telat melunasi cicilan","Total seluruh uang yang dibayar termasuk bunga dan denda","Jumlah uang asli yang dipinjam, sebelum ditambah bunga"],answer:2,explain:"Total yang harus dikembalikan = pokok + bunga (+ denda bila telat). Membedakan keduanya membantu memahami biaya utang.",hint:"Angka mana yang kamu terima di awal?"},
{n:4,type:"mcq",micro:"Bunga: pinjam vs tabung",q:"Saat kamu MENABUNG, bunga menguntungkanmu. Saat kamu MEMINJAM, bunga...",options:["Merugikanmu — kamu yang membayarnya, sehingga barang jadi lebih mahal daripada harga tunai","Tidak berpengaruh pada uangmu, karena bunga hanya angka di atas kertas yang tidak dibayarkan siapa pun","Menguntungkanmu, sebab uang yang kamu pinjam bertambah banyak seiring waktu tanpa perlu kamu bayar lagi"],answer:0,explain:"Bunga selalu berpihak pada pemilik uang. Menabung: kamu pemilik uang. Meminjam: orang lain pemilik uang, kamu membayar.",hint:"Siapa yang membayar bunga saat kamu berutang?"},
{n:5,type:"mcq",micro:"Cicilan",q:"'Cicilan' (angsuran) adalah...",options:["Pembayaran tunai penuh sekaligus di awal tanpa bunga, yang diberikan toko kepada pembeli tertentu saja","Pembayaran utang yang dipecah menjadi jumlah kecil yang dibayar rutin (mis. tiap bulan) sampai lunas","Potongan harga khusus yang diberikan toko kepada pembeli yang membayar dengan cara tunai di kasir"],answer:1,explain:"Cicilan terasa ringan per bulan, tetapi total yang dibayar (pokok + seluruh bunga) hampir selalu lebih besar dari harga tunai.",hint:"Bayar sedikit-sedikit tiap bulan disebut apa?"},
{n:6,type:"mcq",micro:"Denda keterlambatan",q:"Kalau kamu terlambat membayar cicilan, biasanya kena...",options:["Bonus dari pemberi pinjaman — sehingga utangmu berkurang sedikit demi sedikit","Pemutihan utang oleh pemberi pinjaman — sehingga cicilanmu dihapus","Denda (biaya tambahan) — sehingga utangmu bertambah, bukan berkurang"],answer:2,explain:"Telat bayar membuat utang membengkak lewat denda & bunga berjalan. Membayar tepat waktu jauh lebih murah.",hint:"Apakah terlambat bayar membuat utang lebih kecil atau lebih besar?"},
{n:7,type:"mcq",micro:"Harga tunai vs kredit",q:"Sebuah sepeda seharga Rp1.000.000 tunai, atau Rp120.000 × 10 bulan secara kredit. Membeli kredit berarti membayar total...",options:["Rp1.200.000 — Rp200.000 lebih mahal karena bunga","Rp900.000 — Rp100.000 lebih murah karena diskon kredit","Rp1.000.000 — sama dengan harga tunai karena tanpa bunga"],answer:0,explain:"Rp120.000 × 10 = Rp1.200.000. Selisih Rp200.000 adalah biaya berutang (bunga). Kredit hampir selalu lebih mahal.",hint:"Kalikan cicilan dengan jumlah bulan, lalu bandingkan dengan harga tunai."},
{n:8,type:"mcq",micro:"Utang untuk apa",q:"Berutang paling masuk akal ketika...",options:["Untuk membeli jajan, mainan, atau gaya hidup yang nilainya cepat habis, asalkan kamu merasa sangat menginginkannya sekarang","Untuk sesuatu yang penting, tahan lama, atau bisa menambah penghasilan, dan kamu yakin mampu membayar cicilannya","Setiap kali kamu menginginkan sesuatu tetapi belum punya uang, karena berutang adalah cara termudah untuk memilikinya segera"],answer:1,explain:"Utang yang bijak: nilainya bertahan atau tumbuh, cicilannya terjangkau, & ada rencana pembayaran yang jelas.",hint:"Berutang untuk hal yang cepat habis, atau untuk hal penting yang bertahan lama?"},
{n:9,type:"order",micro:"Siklus satu pinjaman",q:"Urutkan tahap sebuah pinjaman sederhana dari awal sampai selesai.",items:["Meminjam sejumlah uang (pokok) & menyepakati bunga serta jadwal bayar","Menerima & memakai uang tersebut","Membayar cicilan rutin (pokok + bunga) tepat waktu","Pinjaman lunas; total yang dibayar lebih besar dari pokok"],answer:[0,1,2,3],explain:"Sepakati → terima & pakai → cicil tepat waktu → lunas. Total bayar = pokok + seluruh bunga.",hint:"Apa yang terjadi paling awal, dan apa yang menandakan selesai?"},
{n:10,type:"mcq",micro:"Bunga per tahun",q:"Bunga pinjaman 'Rp2.000.000, bunga 10% per tahun' berarti dalam setahun kamu membayar bunga sekitar...",options:["Rp20.000 (1% dari Rp2.000.000), di luar pengembalian pokok","Rp2.000.000 (100% dari pinjaman), sama dengan pengembalian pokok","Rp200.000 (10% dari Rp2.000.000), di luar pengembalian pokok"],answer:2,explain:"10% dari Rp2.000.000 = Rp200.000 bunga setahun. Persentase bunga menunjukkan seberapa mahal utang itu.",hint:"Hitung 10% dari dua juta."},
{n:11,type:"tf",micro:"Utang harus dikembalikan",q:"Benar atau Salah: Uang yang dipinjam wajib dikembalikan, biasanya ditambah bunga, sesuai kesepakatan.",answer:true,explain:"Pinjaman adalah janji. Tidak mengembalikannya merusak kepercayaan, menambah denda, & bisa berakibat hukum atau kehilangan agunan.",hint:"Apakah pinjaman itu pemberian gratis?"},
{n:12,type:"mcq",micro:"Meminjam dari teman",q:"Kalau kamu meminjam uang dari teman, hal yang paling menjaga persahabatan adalah...",options:["Menyepakati jumlah & tanggal kembali sejak awal, lalu menepatinya tepat waktu","Menganggap temanmu sudah lupa sehingga tidak perlu mengembalikan kecuali ditagih","Menunda sampai ditagih berkali-kali karena teman yang baik akan mengerti keadaanmu"],answer:0,explain:"Utang yang tidak jelas & tidak dibayar adalah penyebab umum pertengkaran. Kejelasan & ketepatan menjaga hubungan.",hint:"Apa yang membuat teman kesal: janji yang ditepati atau utang yang diabaikan?"},
{n:13,type:"mcq",micro:"Bunga majemuk pada utang",q:"Kalau bunga yang belum dibayar ditambahkan ke pokok, lalu bulan berikutnya bunga dihitung dari jumlah yang lebih besar itu, maka...",options:["Utang tumbuh lambat dan stabil — bunga hanya dihitung dari pokok awal","Utang tumbuh makin cepat — 'bunga berbunga' bekerja melawanmu","Utang menyusut sendiri — bunga yang menumpuk justru bekerja untukmu"],answer:1,explain:"Bunga majemuk hebat untuk tabungan, tetapi menghancurkan bila terjadi pada utang yang menunggak.",hint:"Bunga dihitung dari pokok saja, atau dari pokok + bunga lama?"},
{n:14,type:"tf",micro:"Cicilan ringan bukan berarti murah",q:"Benar atau Salah: Cicilan per bulan yang kecil selalu berarti barangnya jadi lebih murah secara total.",answer:false,explain:"Sebaliknya, cicilan kecil biasanya berarti jangka waktu lebih panjang & total bunga lebih besar. 'Ringan per bulan' sering menyembunyikan 'mahal secara total'.",hint:"Bandingkan total semua cicilan dengan harga tunai."},
{n:15,type:"mcq",micro:"Rentenir",q:"'Rentenir' (lintah darat) adalah pemberi pinjaman tidak resmi yang...",options:["Diawasi ketat oleh lembaga keuangan resmi dan negara, serta menagih dengan cara sopan sesuai aturan","Memberi bunga sangat rendah dan aman bagi peminjam, sehingga cocok bagi yang kekurangan uang mendadak","Menetapkan bunga & denda sangat tinggi serta sering menagih dengan cara mengancam atau memaksa"],answer:2,explain:"Pinjaman rentenir mudah didapat tetapi sangat mahal & berbahaya; utang bisa membengkak berkali lipat dan sulit lepas.",hint:"Bunga sangat tinggi & penagihan kasar — aman atau berbahaya?"},
{n:16,type:"mcq",micro:"Pinjol ilegal",q:"'Pinjaman online ilegal' (pinjol ilegal) berbahaya karena...",options:["Bunganya nol","Bunga mencekik","Data disebar"],answer:0,explain:"Pinjol ilegal tidak diawasi, kerap menipu, membebani bunga liar, & mempermalukan korban. Hindari sama sekali.",hint:"Bunga liar + sebar data + teror kontak — itu tanda apa?"},
{n:17,type:"mcq",micro:"Agunan / jaminan",q:"'Agunan' (jaminan) sebuah pinjaman adalah...",options:["Hadiah dari bank berupa barang berharga yang boleh kamu bawa pulang setelah pinjamanmu disetujui","Barang berharga (mis. sertifikat rumah, kendaraan) yang bisa diambil pemberi pinjaman kalau kamu gagal membayar","Bunga tambahan yang harus dibayar di muka kepada pemberi pinjaman sebelum uang pinjamannya dicairkan"],answer:1,explain:"Agunan mengurangi risiko pemberi pinjaman, tetapi kamu bisa kehilangan barang itu bila menunggak.",hint:"Apa yang bisa disita kalau kamu tidak melunasi?"},
{n:18,type:"mcq",micro:"Gagal bayar",q:"'Gagal bayar' (kredit macet) terjadi ketika peminjam...",options:["Melunasi utang lebih cepat","Tidak mampu membayar cicilan sesuai kesepakatan dalam waktu lama","Membayar tepat waktu setiap bulan"],answer:2,explain:"Gagal bayar berakibat denda menumpuk, agunan disita, nama masuk daftar hitam kredit, & stres berat.",hint:"Berhenti membayar dalam jangka panjang disebut apa?"},
{n:19,type:"mcq",micro:"Aturan aman berutang",q:"Aturan sederhana sebelum berutang:",options:["Pinjam hanya jika kamu tahu persis total biayanya, cicilannya muat di anggaran, & untuk kebutuhan penting — bukan keinginan sesaat","Tidak perlu memikirkan cara membayarnya sekarang, karena uangnya akan ada nanti, yang penting pinjamannya disetujui dulu","Pinjam sebanyak yang disetujui pemberi pinjaman, karena kesempatan seperti itu belum tentu datang lagi di kemudian hari"],answer:0,explain:"Berutang dengan sadar: tahu total biaya, mampu mencicil, & tujuannya benar-benar penting.",hint:"Apa 3 hal yang harus kamu pastikan lebih dulu?"},
{n:20,type:"open",micro:"Membandingkan tunai & kredit",q:"Sebuah ponsel seharga Rp3.000.000 tunai. Toko menawarkan kredit Rp350.000 × 10 bulan tanpa uang muka. Jelaskan: (1) total yang dibayar lewat kredit, (2) berapa biaya tambahan berutang, (3) dalam situasi apa kredit ini masih bisa masuk akal, dan (4) satu cara mendapatkan ponsel tanpa berutang.",explain:"Jawaban baik menghitung total kredit (Rp3.500.000), biaya bunga (Rp500.000), menyebut syarat wajar berutang (butuh, cicilan terjangkau, tak ada opsi lain), & memberi alternatif menabung atau membeli bekas.",hint:"Kalikan cicilan × bulan, kurangi harga tunai, lalu pikirkan kapan berutang wajar.",sample:"(1) Total kredit = Rp350.000 × 10 = Rp3.500.000. (2) Biaya tambahan berutang = Rp3.500.000 − Rp3.000.000 = Rp500.000 (bunga). (3) Kredit ini mungkin masuk akal bila ponsel benar-benar dibutuhkan sekarang (mis. untuk kerja/sekolah), cicilan Rp350.000 nyaman muat di anggaran bulanan tanpa mengorbankan kebutuhan pokok, dan tidak ada tabungan yang bisa dipakai. (4) Tanpa berutang: menabung Rp350.000 per bulan selama 9 bulan lalu membeli tunai (bahkan lebih murah, Rp3.000.000), atau membeli ponsel bekas yang layak dengan harga jauh lebih rendah."},
{n:21,type:"classify",micro:"Utang produktif vs konsumtif",q:"Kelompokkan tiap contoh utang ke 'Cenderung produktif/masuk akal' atau 'Cenderung konsumtif/berisiko'.",items:["Pinjaman modal untuk alat usaha yang menambah penghasilan","Kredit untuk liburan mewah yang tak terjangkau","Cicilan gawai murah demi mengikuti tren teman","Pinjaman biaya kursus keterampilan yang meningkatkan peluang kerja"],groups:["Cenderung produktif/masuk akal","Cenderung konsumtif/berisiko"],answer:{"Cenderung produktif/masuk akal":["Pinjaman modal untuk alat usaha yang menambah penghasilan","Pinjaman biaya kursus keterampilan yang meningkatkan peluang kerja"],"Cenderung konsumtif/berisiko":["Kredit untuk liburan mewah yang tak terjangkau","Cicilan gawai murah demi mengikuti tren teman"]},explain:"Utang produktif berpotensi menambah nilai atau penghasilan. Utang konsumtif membiayai barang/kegiatan yang cepat habis nilainya & tidak menghasilkan.",hint:"Apakah utang ini bisa membantumu menghasilkan lebih, atau hanya menghabiskan?"},
{n:22,type:"mcq",micro:"Utang baik vs buruk",q:"Ciri utama 'utang buruk' adalah...",options:["Berjumlah kecil, misalnya hanya beberapa ribu rupiah, sehingga cicilannya hampir tidak terasa dalam anggaranmu","Dipakai untuk hal yang cepat kehilangan nilai atau habis, dengan bunga tinggi & cicilan yang memberatkan anggaran","Dipakai untuk aset penting yang tahan lama dengan cicilan terjangkau, sehingga manfaatnya melebihi biayanya"],answer:1,explain:"Bukan besar-kecilnya yang menentukan, melainkan tujuan, biaya bunga, & apakah cicilannya sehat bagi keuanganmu.",hint:"Untuk apa uangnya dipakai, & seberapa berat cicilannya?"},
{n:23,type:"mcq",micro:"Jangka waktu & bunga",q:"Untuk pinjaman dengan bunga yang sama, memperpanjang jangka waktu cicilan biasanya membuat...",options:["Total bunga lebih besar","Cicilan bulanan lebih kecil","Total bunga lebih kecil"],answer:2,explain:"Makin lama berutang, makin lama bunga berjalan. Cicilan 'enteng' menukar kenyamanan bulanan dengan biaya total lebih tinggi.",hint:"Bunga berjalan selama utang belum lunas — lebih lama berarti apa?"},
{n:24,type:"mcq",micro:"Membaca bunga (APR)",q:"Saat membandingkan dua pinjaman, angka yang paling berguna untuk menilai 'mana yang lebih mahal' adalah...",options:["Warna brosurnya","Persentase bunga per tahun (dan semua biaya), bukan sekadar nominal cicilan bulanan","Nama tokonya"],answer:0,explain:"Cicilan bulanan bisa dibuat terlihat kecil dengan memperpanjang tenor. Persentase bunga tahunan + biaya adalah pembanding yang jujur.",hint:"Nominal cicilan bisa menyesatkan; persentase per tahun lebih jujur."},
{n:25,type:"mcq",micro:"Biaya tersembunyi pinjaman",q:"Selain bunga, pinjaman sering punya biaya lain seperti...",options:["Hanya hadiah dan potongan harga yang diberikan pemberi pinjaman kepada peminjam baru","Biaya administrasi, biaya provisi, asuransi wajib, denda telat, & biaya pelunasan dipercepat","Hanya bunga pokok; biaya lain sudah termasuk dalam cicilan dan tidak boleh ditagih terpisah"],answer:1,explain:"'Bunga rendah' bisa menipu bila biaya lain tinggi. Tanyakan 'total semua biaya' sebelum menandatangani.",hint:"Apakah bunga satu-satunya angka yang perlu kamu tanyakan?"},
{n:26,type:"mcq",micro:"Kartu kredit (gagasan)",q:"Kartu kredit pada dasarnya adalah...",options:["Rekening tabungan milikmu sendiri: kamu hanya memakai saldo yang tersedia, sehingga bank tidak menagih bunga ataupun cicilan","Kartu debit biasa: uang langsung terpotong dari saldo rekeningmu saat transaksi, dan kamu tidak meminjam dari bank","Fasilitas berutang: bank menalangi belanjamu, dan kamu harus melunasinya — kena bunga tinggi bila tidak dibayar penuh tepat waktu"],answer:2,explain:"Dipakai disiplin (lunas penuh tiap bulan) kartu kredit adalah alat; dipakai asal gesek, ia jebakan utang berbunga tinggi.",hint:"Uang di kartu kredit itu milikmu atau pinjaman dari bank?"},
{n:27,type:"tf",micro:"Bayar minimum kartu kredit",q:"Benar atau Salah: Membayar hanya 'tagihan minimum' kartu kredit setiap bulan adalah cara cerdas dan murah untuk melunasi utang.",answer:false,explain:"Sebaliknya, membayar minimum membuat sisa utang terus berbunga tinggi sehingga pelunasan berlangsung bertahun-tahun & total biayanya bisa berlipat. Lunasi penuh bila mungkin.",hint:"Kalau hanya bayar sedikit, sisa besarnya kena apa?"},
{n:28,type:"mcq",micro:"Skor / riwayat kredit",q:"'Riwayat kredit' (catatan bagaimana seseorang membayar utang) penting karena...",options:["Dipakai bank & lembaga lain menilai apakah seseorang layak dipinjami; riwayat buruk menyulitkan mendapat pinjaman, KPR, bahkan pekerjaan tertentu","Hanya berlaku selama satu bulan lalu terhapus sendiri, sehingga cara kamu membayar utang tidak memengaruhi pinjaman, KPR, atau pekerjaanmu kelak","Dipakai terutama untuk menentukan besar pajak tahunan seseorang, bukan untuk menilai kelayakan pinjaman; riwayat buruk tidak berdampak pada KPR atau pekerjaan"],answer:0,explain:"Membayar tepat waktu membangun reputasi keuangan. Menunggak merusaknya untuk waktu lama.",hint:"Kenapa membayar tepat waktu penting untuk masa depan?"},
{n:29,type:"mcq",micro:"Tanda bahaya pinjaman",q:"Tawaran pinjaman yang perlu diwaspadai biasanya...",options:["Menjelaskan semua biaya secara terbuka dan memberi waktu cukup untuk berpikir, serta tidak meminta akses data pribadi berlebihan","Mendesak 'sekarang juga', menutupi total biaya, meminta akses data pribadi berlebihan, atau menjanjikan 'pasti cair tanpa syarat'","Diawasi oleh otoritas keuangan resmi dan memiliki izin yang bisa dicek, dengan bunga dan denda yang tertulis jelas di awal"],answer:1,explain:"Tekanan waktu, biaya tidak jelas, & permintaan data berlebihan adalah ciri pinjaman menipu atau ilegal.",hint:"Mendesak, tidak transparan, minta data banyak — aman atau curiga?"},
{n:30,type:"order",micro:"Menghitung total biaya kredit",q:"Urutkan langkah menghitung berapa mahal sebuah kredit dibanding tunai.",items:["Catat harga tunai barang","Kalikan cicilan per bulan dengan jumlah bulan","Tambahkan uang muka & semua biaya administrasi","Kurangi total kredit dengan harga tunai — selisihnya adalah biaya berutang"],answer:[0,1,2,3],explain:"Harga tunai → total cicilan → + uang muka & biaya → bandingkan. Selisih = biaya berutang.",hint:"Kamu butuh dua angka besar untuk dibandingkan: total kredit dan harga tunai."},
{n:31,type:"mcq",micro:"Rasio cicilan terhadap penghasilan",q:"Pedoman umum yang sering dipakai: total seluruh cicilan utang per bulan sebaiknya tidak melebihi sekitar...",options:["90% dari penghasilan bulanan","Sama dengan seluruh penghasilan","30% dari penghasilan bulanan"],answer:2,explain:"Bila cicilan menyita terlalu banyak penghasilan, satu kejadian tak terduga (sakit, kehilangan kerja) bisa memicu gagal bayar.",hint:"Sepertiga penghasilan, atau hampir seluruhnya?"},
{n:32,type:"tf",micro:"Menutup utang dengan utang baru",q:"Benar atau Salah: Terus-menerus meminjam dari tempat baru hanya untuk membayar utang lama ('gali lubang tutup lubang') justru membuat total utang membesar karena setiap pinjaman baru menambah bunga & biaya.",answer:true,explain:"Pola ini menambah beban di tiap langkah & merupakan tanda kesulitan keuangan yang butuh solusi nyata (hemat, tambah pemasukan, negosiasi), bukan pinjaman lagi.",hint:"Apakah menambah pinjaman baru membuat total utang lebih kecil atau lebih besar?"},
{n:33,type:"mcq",micro:"Dana darurat vs utang",q:"Punya dana darurat membantu menghindari utang karena...",options:["Saat ada kejadian tak terduga (motor rusak, sakit), kamu bisa membayarnya dari tabungan, bukan meminjam dengan bunga","Dana darurat dipakai untuk membeli barang keinginan yang sedang diskon, sehingga tidak berkaitan dengan kejadian tak terduga","Dana darurat sebaiknya diinvestasikan penuh di saham agar berlipat ganda, lalu kejadian tak terduga ditutup dengan pinjaman"],answer:0,explain:"Tanpa bantalan tabungan, kejutan hidup memaksa orang berutang. Dana darurat memutus siklus itu.",hint:"Dari mana uang untuk keadaan darurat kalau bukan tabungan?"},
{n:34,type:"mcq",micro:"Bunga 'flat' vs 'efektif'",q:"Bunga yang dihitung selalu dari pokok awal (bunga 'flat') dibanding bunga yang dihitung dari sisa utang (bunga 'efektif'), pada persen yang sama...",options:["Bunga flat membuat total bayar lebih kecil, karena bunganya dihitung dari saldo yang terus turun","Bunga flat membuat total bayar lebih besar, karena tidak ikut turun saat pokok berkurang","Total bayar keduanya sama, karena bunga flat dan bunga efektif hanya beda nama untuk perhitungan yang sama"],answer:1,explain:"Angka persen yang terlihat sama bisa berarti biaya berbeda. Tanyakan cara bunga dihitung, bukan hanya angkanya.",hint:"Kalau bunga tetap dihitung dari jumlah awal meski utang sudah berkurang, adilkah?"},
{n:35,type:"mcq",micro:"Menjamin utang orang lain",q:"Menjadi 'penjamin' utang orang lain berarti...",options:["Kamu hanya diminta memberi dukungan moral, sedangkan utang yang gagal dibayar ditanggung pemberi pinjaman","Kamu ikut menerima sebagian uang pinjamannya, tetapi utang yang gagal dibayar tetap ditanggung peminjam","Kalau orang itu gagal bayar, kamu yang wajib melunasi utang tersebut dengan hartamu sendiri"],answer:2,explain:"Menjamin utang orang lain adalah risiko besar; banyak persahabatan & keluarga rusak karenanya. Pikirkan masak-masak.",hint:"Kalau si peminjam kabur, siapa yang ditagih?"},
{n:36,type:"mcq",micro:"Meminjamkan uang ke teman",q:"Kalau temanmu meminjam uang & kamu ragu ia bisa mengembalikannya, sikap paling bijak:",options:["Hanya pinjamkan jumlah yang kamu ikhlas bila tidak kembali, & sepakati waktu pengembalian secara jelas","Pinjamkan tanpa kesepakatan tertulis supaya temanmu tidak merasa dicurigai, dan tagih saja kalau sudah lama","Pinjamkan sebesar yang diminta, termasuk dari tabungan inti, karena pertemanan lebih berharga daripada uang"],answer:0,explain:"Meminjamkan uang berisiko merusak hubungan. Batasi ke jumlah yang tidak menyakitkan bila hilang.",hint:"Berapa jumlah yang tidak akan membuatmu marah bila tak dikembalikan?"},
{n:37,type:"tf",micro:"Promo '0%' selalu benar-benar gratis",q:"Benar atau Salah: Cicilan 'bunga 0%' selalu berarti kamu membayar persis sama dengan harga tunai, tanpa biaya apa pun.",answer:false,explain:"Sebaliknya, promo 0% sering disertai biaya administrasi, harga yang sudah dinaikkan, syarat kartu tertentu, atau denda besar bila telat sekali saja. Baca syaratnya.",hint:"Kalau 0%, dari mana toko & bank untung?"},
{n:38,type:"mcq",micro:"Membayar utang lebih cepat",q:"Melunasi utang berbunga tinggi lebih cepat dari jadwal (bila tidak ada penalti) biasanya...",options:["Merugikan karena kamu kehilangan keuntungan cicilan, jadi lebih baik dicicil terus","Menguntungkan karena menghentikan bunga berjalan sehingga total biaya turun","Tidak ada bedanya, karena total bayar tetap sama seperti jika dicicil penuh"],answer:1,explain:"Setiap bulan lebih cepat lunas adalah bulan tanpa bunga. Cek dulu apakah ada 'penalti pelunasan dipercepat'.",hint:"Bunga berhenti saat utang lunas — lebih cepat lunas berarti apa?"},
{n:39,type:"mcq",micro:"Prioritas melunasi banyak utang",q:"Kalau punya beberapa utang, strategi yang menghemat paling banyak uang adalah membayar ekstra pada utang...",options:["Dengan bunga paling rendah lebih dulu, sambil tetap membayar minimum pada utang yang lain","Dengan usia paling tua lebih dulu, tanpa melihat bunga, sambil membayar minimum yang lain","Dengan bunga paling tinggi lebih dulu (sambil tetap membayar minimum yang lain)"],answer:2,explain:"Utang berbunga tertinggi tumbuh paling cepat; menyerangnya lebih dulu memangkas total bunga terbanyak.",hint:"Utang mana yang paling 'mahal' setiap bulannya?"},
{n:40,type:"open",micro:"Menilai tawaran pinjol",q:"Sebuah aplikasi mengirim SMS: 'Selamat! Dana Rp2.000.000 siap cair HARI INI tanpa jaminan, tanpa slip gaji. Klik link, isi data KTP, kontak keluarga, & foto selfie. Bunga hanya 0,8% per HARI.' Sebutkan minimal 4 tanda bahaya dan apa yang sebaiknya dilakukan.",explain:"Jawaban baik mengenali bunga harian yang liar, tekanan waktu, permintaan data pribadi & kontak berlebihan, janji 'pasti cair', dan menyimpulkan: jangan tanggapi, blokir, dan cari sumber dana yang aman & resmi.",hint:"Hitung bunga per hari menjadi per bulan, dan perhatikan data apa yang diminta serta seberapa memaksa pesan itu.",sample:"Tanda bahaya: (1) Bunga 0,8% per hari = sekitar 24% per bulan / hampir 290% per tahun — sangat mencekik, jauh di atas pinjaman resmi. (2) Mendesak 'cair HARI INI', menekan agar tidak sempat berpikir. (3) Meminta akses kontak keluarga & selfie memegang KTP — ciri pinjol ilegal yang akan meneror & mempermalukan bila telat bayar. (4) 'Tanpa jaminan, tanpa slip gaji, pasti cair' — pemberi pinjaman sah selalu menilai kemampuan bayar. (5) Datang lewat SMS/link tak dikenal. Yang sebaiknya dilakukan: jangan klik link, jangan isi data apa pun, hapus pesan, blokir nomor, dan bila butuh dana bicarakan dengan keluarga atau cari lembaga resmi yang diawasi otoritas keuangan. Laporkan nomor tersebut ke kanal pengaduan resmi."},
{n:41,type:"mcq",micro:"Hitung total cicilan",q:"Kamu mengambil kredit sepeda motor: uang muka Rp2.000.000, lalu Rp900.000 × 24 bulan. Total uang yang kamu keluarkan adalah...",options:["Rp2.000.000 + (Rp900.000 × 24) = Rp23.600.000","Rp900.000 × 24 = Rp21.600.000 tanpa uang muka","Rp2.000.000 + (Rp900.000 × 12) = Rp12.800.000"],answer:0,explain:"Total = uang muka + seluruh cicilan = Rp2.000.000 + Rp21.600.000 = Rp23.600.000. Bandingkan dengan harga tunainya.",hint:"Jangan lupa menambahkan uang muka ke total cicilan."},
{n:42,type:"mcq",micro:"Biaya bunga sebenarnya",q:"Motor pada soal sebelumnya berharga Rp19.000.000 tunai. Biaya tambahan karena mengkredit adalah...",options:["Rp19.000.000 − Rp23.600.000 = −Rp4.600.000","Rp23.600.000 − Rp19.000.000 = Rp4.600.000","Rp23.600.000 − Rp2.000.000 = Rp21.600.000"],answer:1,explain:"Selisih Rp4.600.000 adalah harga yang kamu bayar untuk 'memiliki sekarang, bayar belakangan'.",hint:"Total yang dikeluarkan dikurangi harga tunai."},
{n:43,type:"mcq",micro:"Cicilan muat di anggaran?",q:"Penghasilan bersih keluarga Rp4.000.000/bulan. Sudah ada cicilan lain Rp700.000. Menambah cicilan motor Rp900.000 membuat total cicilan Rp1.600.000, yaitu...",options:["15% dari penghasilan — jauh di bawah pedoman, sangat aman","25% dari penghasilan — di bawah pedoman ~30% & aman","40% dari penghasilan — melewati pedoman ~30% & berisiko"],answer:2,explain:"Rp1.600.000 ÷ Rp4.000.000 = 40%. Melebihi batas aman; satu kejutan keuangan bisa memicu gagal bayar.",hint:"Bagi total cicilan dengan penghasilan, ubah ke persen."},
{n:44,type:"mcq",micro:"Menabung dulu vs kredit",q:"Alih-alih mengkredit motor Rp19.000.000 dengan biaya bunga Rp4.600.000, keluarga bisa...",options:["Menabung Rp900.000/bulan selama ~21 bulan lalu membeli tunai — menghindari bunga & malah lebih murah","Mengambil kredit saja sekarang karena menabung hampir dua tahun terasa terlalu lama bagi keluarga biasa","Meminjam dari pemberi pinjaman informal yang prosesnya cepat tanpa syarat, lalu melunasi bila ada uang"],answer:0,explain:"Menabung menunda kepemilikan tetapi menghemat jutaan rupiah bunga. Bila motor tidak mendesak, menabung menang.",hint:"Uang yang tadinya untuk cicilan bisa dialihkan ke mana lebih dulu?"},
{n:45,type:"order",micro:"Langkah saat kesulitan membayar utang",q:"Urutkan langkah bijak ketika mulai kesulitan membayar cicilan.",items:["Akui masalahnya lebih awal & buat daftar semua utang, bunga, & jatuh temponya","Pangkas pengeluaran tidak penting & cari tambahan penghasilan","Hubungi pemberi pinjaman resmi untuk minta keringanan/penjadwalan ulang","Bayar dulu utang berbunga tertinggi & yang paling berisiko (agunan/legal)"],answer:[0,1,2,3],explain:"Hadapi lebih awal → hemat & tambah pemasukan → negosiasi → prioritaskan utang termahal/paling berisiko. Menghindar hanya memperburuk.",hint:"Apa yang harus dilakukan lebih dulu: menghadapi atau menghindar?"},
{n:46,type:"mcq",micro:"Denda menumpuk",q:"Cicilan Rp500.000 telat 3 bulan, denda Rp50.000 per bulan keterlambatan. Selain menunggak Rp1.500.000 pokok cicilan, kamu juga berutang denda...",options:["Rp0 (belum ada denda), sehingga total tunggakan tetap Rp1.500.000","Rp150.000 (Rp50.000 × 3), sehingga total tunggakan Rp1.650.000","Rp50.000 (sekali saja), sehingga total tunggakan Rp1.550.000"],answer:1,explain:"Telat membuat utang bertambah, bukan berkurang. Denda + bunga berjalan mempercepat pembengkakan.",hint:"Kalikan denda bulanan dengan jumlah bulan telat, lalu tambahkan ke tunggakan pokok."},
{n:47,type:"mcq",micro:"Keinginan mendesak",q:"Temanmu semua punya sepatu edisi terbatas Rp1.500.000. Kamu tak punya uang & tergoda pinjol. Keputusan paling sehat:",options:["Pinjam dari dua aplikasi pinjol sekaligus untuk berjaga-jaga, supaya uangnya cukup membeli sepatu dan masih ada sisanya","Pinjam agar tidak ketinggalan tren seperti teman-temanmu, dan pikirkan cara membayarnya nanti ketika tagihan mulai datang","Tidak berutang untuk barang gaya hidup; menabung bila memang mau, atau merelakannya — tren berganti, utang berbunga tetap menagih"],answer:2,explain:"Berutang demi gengsi adalah utang konsumtif paling merugikan: nilainya cepat pudar, cicilannya tidak.",hint:"Sepatu tren tahun ini masih penting tahun depan? Utangnya masih ada?"},
{n:48,type:"mcq",micro:"Pinjaman produktif yang wajar",q:"Ibu meminjam Rp3.000.000 untuk mesin jahit; dari jahitan ia berpotensi memperoleh tambahan Rp1.500.000/bulan, cicilan Rp600.000 × 6 bulan. Ini contoh...",options:["Utang yang berpotensi produktif: aset dipakai menghasilkan, tambahan penghasilan jauh di atas cicilan, tenor pendek","Utang konsumtif: barang dipakai untuk bersenang-senang, tidak menambah penghasilan, dan cicilannya berjalan bertahun-tahun","Utang gaya hidup yang dibayar dari kartu kredit, dengan tenor panjang dan manfaat yang cepat hilang setelah dipakai"],answer:0,explain:"Utang bisa masuk akal bila aset menghasilkan arus kas yang menutup cicilan dengan lega & rencananya realistis.",hint:"Apakah barang yang dibeli bisa menghasilkan uang lebih besar dari cicilannya?"},
{n:49,type:"mcq",micro:"Membaca kontrak",q:"Sebelum menandatangani perjanjian pinjaman, hal wajib dilakukan:",options:["Menandatangani dengan cepat agar tidak dianggap curiga oleh petugas, karena isi perjanjian standar dan sama untuk peminjam lain","Membaca seluruh isi (bunga, semua biaya, denda, agunan, akibat gagal bayar), menanyakan yang tidak jelas, & menyimpan salinannya","Mempercayai penjelasan lisan petugas dan menyimpan perjanjian tanpa dibaca, karena petugas sudah menjelaskan hal penting"],answer:1,explain:"Tanda tangan mengikat secara hukum. Apa pun yang tidak kamu pahami bisa merugikanmu kemudian.",hint:"Dokumen yang mengikat secara hukum sebaiknya dibaca dulu atau nanti?"},
{n:50,type:"open",micro:"Utang berbunga majemuk yang menunggak",q:"Utang Rp1.000.000 dengan bunga 10% per bulan yang dibiarkan menunggak (bunga ditambahkan ke pokok tiap bulan). Perkirakan besar utang setelah 1, 2, dan 3 bulan, lalu jelaskan pelajarannya.",explain:"Jawaban baik mengalikan saldo dengan 1,1 tiap bulan (Rp1.100.000; Rp1.210.000; Rp1.331.000) & menyimpulkan bahwa bunga berbunga membuat utang tumbuh cepat, sehingga menunda bayar sangat merugikan.",hint:"Setiap bulan, kalikan jumlah utang saat itu dengan 1,1 (tambah 10%).",sample:"Bulan 0: Rp1.000.000. Bulan 1: Rp1.000.000 × 1,1 = Rp1.100.000. Bulan 2: Rp1.100.000 × 1,1 = Rp1.210.000. Bulan 3: Rp1.210.000 × 1,1 = Rp1.331.000. Dalam 3 bulan saja utang naik Rp331.000 (33%) tanpa membeli apa pun. Pelajaran: bunga majemuk pada utang menunggak membuat kewajiban tumbuh makin cepat karena bunga dihitung dari jumlah yang terus membesar. Karena itu utang berbunga tinggi harus dilunasi secepat mungkin, dan menunda pembayaran justru paling mahal."},
{n:51,type:"mcq",micro:"Pilihan sumber pinjaman",q:"Bila benar-benar harus meminjam, urutan sumber dari umumnya paling aman ke paling berbahaya kira-kira:",options:["Pinjol ilegal lebih dulu karena paling cepat cair dan tidak banyak syarat, baru bank resmi bila pinjol ilegal menolak","Rentenir lebih dulu, kemudian pinjol ilegal, dan terakhir bank atau koperasi resmi, karena yang terakhir prosesnya paling lama","Keluarga/koperasi & bank resmi yang diawasi → lembaga kredit resmi lain → hindari rentenir & pinjol ilegal"],answer:2,explain:"Sumber resmi yang diawasi punya aturan bunga & penagihan yang jelas. Rentenir & pinjol ilegal adalah jalan terakhir yang sebaiknya tidak pernah diambil.",hint:"Mana yang diawasi otoritas & mana yang tidak?"},
{n:52,type:"tf",micro:"Utang bukan penghasilan",q:"Benar atau Salah: Uang pinjaman yang cair ke rekening boleh dianggap sebagai 'penghasilan' dan dibelanjakan bebas.",answer:false,explain:"Sebaliknya, uang pinjaman adalah kewajiban, bukan penghasilan. Ia harus dikembalikan dengan bunga, jadi sebaiknya dipakai hanya untuk tujuan yang direncanakan.",hint:"Apakah uang itu menjadi milikmu, atau harus dikembalikan?"},
{n:53,type:"mcq",micro:"Godaan limit kartu kredit",q:"Bank menaikkan limit kartu kreditmu dari Rp5 juta ke Rp15 juta. Ini berarti...",options:["Kemampuan berutangmu bertambah — bukan uangmu; kalau dipakai, semua tetap harus dilunasi dengan bunga","Kamu wajib memakai limit baru itu tiap bulan, supaya bank tidak menurunkannya lagi pada bulan berikutnya","Uangmu bertambah Rp10 juta karena bank memasukkannya ke tabungan, sehingga boleh dibelanjakan bebas"],answer:0,explain:"Limit besar bukan tabungan. Menganggapnya 'uang lebih' adalah awal jebakan utang kartu kredit.",hint:"Limit naik menambah uangmu, atau menambah maksimum utangmu?"},
{n:54,type:"mcq",micro:"Refinancing / take over",q:"Memindahkan utang ke pemberi pinjaman lain dengan bunga lebih rendah bisa membantu, ASALKAN...",options:["Kamu sekaligus menambah pinjaman baru di tempat lama juga, karena limit yang kosong bisa dipakai untuk belanja kebutuhan lain","Bunga & seluruh biaya baru benar-benar lebih rendah, tenor tidak diperpanjang diam-diam, & kamu tidak tergoda berutang lagi di tempat lama","Pemberi pinjaman baru dikenal baik di media sosial dan petugasnya ramah, sehingga tawarannya layak dipercaya tanpa dihitung ulang"],answer:1,explain:"'Pindah utang' bermanfaat hanya bila total biaya turun & disiplinnya terjaga. Kalau tidak, itu sekadar menunda masalah.",hint:"Apa syarat agar memindahkan utang benar-benar menghemat?"},
{n:55,type:"mcq",micro:"Menolak dengan sopan",q:"Saudara memaksamu menjadi penjamin pinjamannya Rp50 juta. Kamu ragu ia mampu bayar. Respons paling bijak:",options:["Menandatangani sambil berharap saudaramu bisa membayar, karena kamu sudah terlanjur dimintai tolong dan sulit menolak","Menandatangani agar tidak dianggap pelit dan tidak merusak hubungan keluarga, karena risikonya kecil dan jarang terjadi","Menolak dengan jujur & sopan: menjelaskan bahwa kamu tak sanggup menanggung risiko melunasi Rp50 juta bila terjadi gagal bayar"],answer:2,explain:"Penjamin menanggung utang penuh bila peminjam gagal. Menolak risiko yang tidak sanggup kamu pikul adalah keputusan dewasa, bukan kejahatan.",hint:"Kalau ia gagal bayar, apakah kamu benar-benar sanggup melunasi Rp50 juta?"},
{n:56,type:"mcq",micro:"Tergiur 'diskon' via kredit",q:"Toko menawarkan TV 'diskon 20%' tapi hanya bila diambil kredit 12 bulan dengan bunga yang menambah 25% dari harga. Secara total kamu...",options:["Tetap membayar lebih mahal daripada harga normal tunai, karena tambahan bunga 25% melebihi diskon 20%","Hemat 45% dari harga normal tunai, karena diskon 20% dan bunga 25% sama-sama menurunkan harga","Impas dengan harga normal tunai, karena diskon 20% persis menutup tambahan bunga cicilan"],answer:0,explain:"Diskon di depan bisa 'dimakan' bunga di belakang. Selalu bandingkan total akhir kredit dengan harga tunai biasa.",hint:"Diskon 20% lalu ditambah bunga 25% — hasil akhirnya naik atau turun?"},
{n:57,type:"tf",micro:"Meminjam untuk investasi berisiko",q:"Benar atau Salah: Meminjam uang berbunga untuk ditaruh di investasi yang harganya naik-turun tajam adalah cara aman menjadi kaya cepat.",answer:false,explain:"Sebaliknya, ini sangat berbahaya: bila investasi merugi, kamu kehilangan uang sekaligus tetap wajib membayar utang + bunga. Jangan berutang untuk berspekulasi.",hint:"Apa yang terjadi kalau investasinya turun tetapi utangnya tetap?"},
{n:58,type:"mcq",micro:"Uang muka besar",q:"Memberi uang muka lebih besar saat mengambil kredit umumnya membuat...",options:["Pokok utang tetap sama, sehingga total bunga & cicilan tidak berubah","Pokok utang lebih kecil, sehingga total bunga & cicilan lebih ringan","Pokok utang lebih kecil, tetapi total bunga & cicilan justru lebih berat"],answer:1,explain:"Makin sedikit yang dipinjam, makin sedikit bunga. Bila terpaksa kredit, perbesar uang muka & perpendek tenor.",hint:"Bunga dihitung dari jumlah yang dipinjam — meminjam lebih sedikit berarti apa?"},
{n:59,type:"mcq",micro:"Tekanan penagih",q:"Kalau seorang penagih utang mengancam, mempermalukan di depan umum, atau menghubungi semua kontakmu, itu...",options:["Berarti utangmu dianggap lunas karena penagih melanggar aturan, sehingga kamu tidak perlu membayar sisa utang kepada pemberi pinjaman","Hal wajar yang harus diikuti peminjam, karena penagih berhak menekan dan mengancam orang yang terlambat membayar cicilan","Melanggar aturan penagihan yang sah; kamu berhak melapor ke otoritas/lembaga perlindungan konsumen & tetap menyelesaikan utang lewat jalur resmi"],answer:2,explain:"Utang tetap harus diselesaikan, tetapi penagihan wajib beretika & sesuai hukum. Intimidasi bisa dilaporkan.",hint:"Utang nyata, tapi apakah cara menagih boleh dengan ancaman?"},
{n:60,type:"open",micro:"Rencana keluar dari utang",q:"Seseorang punya 3 utang: (A) pinjol Rp1.500.000 bunga sangat tinggi, cicilan Rp400.000/bln; (B) cicilan HP Rp2.000.000, sisa 5 × Rp450.000; (C) utang ke saudara Rp1.000.000 tanpa bunga, fleksibel. Penghasilan tersisa untuk utang Rp1.200.000/bulan. Susun rencana 3-4 langkah.",explain:"Jawaban baik memprioritaskan utang berbunga tertinggi (pinjol A) setelah mengamankan kewajiban minimum, memanfaatkan keluwesan utang tanpa bunga (C) untuk ditunda, lalu berturut-turut melunasi B dan C, sambil memangkas biaya, menambah pemasukan, dan berhenti berutang baru.",hint:"Amankan yang wajib & berisiko dulu, lalu serang bunga tertinggi, manfaatkan utang tanpa bunga yang fleksibel sebagai yang terakhir.",sample:"Langkah 1: Bayar minimum yang wajib untuk B (Rp450.000) agar HP tidak ditarik & catatan kredit aman, dan bicarakan dengan saudara (C) untuk menunda pembayaran sementara karena tanpa bunga & fleksibel. Langkah 2: Kerahkan sisa dana (Rp1.200.000 − Rp450.000 = Rp750.000) untuk menyerang utang A (pinjol berbunga tertinggi) sampai lunas secepat mungkin, sekitar 2 bulan, karena inilah utang termahal. Langkah 3: Setelah A lunas, alihkan seluruh Rp1.200.000 untuk mempercepat pelunasan B. Langkah 4: Terakhir, lunasi C ke saudara sesuai janji, dan mulai bangun dana darurat kecil agar tidak kembali ke pinjol. Selama proses: pangkas pengeluaran tidak penting & cari tambahan penghasilan, serta berhenti mengambil utang baru."},
{n:61,type:"mcq",micro:"Mengapa bunga ada",q:"Alasan mendasar pemberi pinjaman menetapkan bunga:",options:["Sebagai imbalan atas waktu (uang tak bisa dipakai sendiri), risiko gagal bayar, & pengaruh inflasi terhadap nilai uang","Karena mereka wajib membagikan hadiah kepada peminjam, sehingga bunga hanyalah cara mengembalikan hadiah itu","Untuk mempersulit peminjam tanpa alasan yang jelas, sebab pemberi pinjaman senang jika peminjam kesulitan membayar"],answer:0,explain:"Bunga menutup 'biaya kesempatan', risiko, & inflasi. Makin berisiko peminjam, makin tinggi bunga yang diminta.",hint:"Apa yang dikorbankan & dipertaruhkan pemilik uang saat meminjamkan?"},
{n:62,type:"mcq",micro:"Bunga tinggi = risiko tinggi",q:"Pinjaman 'tanpa syarat, langsung cair' biasanya berbunga sangat tinggi karena...",options:["Aturan pemerintah mewajibkan bunga setinggi itu, sehingga pemberi pinjaman hanya menjalankan ketentuan","Pemberi pinjaman tidak menilai kemampuan bayar, sehingga menutup risiko gagal bayar yang besar dengan bunga selangit","Mereka lembaga sosial yang menolong masyarakat, sehingga bunga tinggi dipakai untuk membiayai bantuan"],answer:1,explain:"Kemudahan berutang berbanding lurus dengan mahalnya bunga. 'Gampang cair' hampir selalu berarti 'sangat mahal'.",hint:"Kalau pemberi pinjaman tidak memeriksa apa pun, bagaimana ia melindungi diri dari kerugian?"},
{n:63,type:"tf",micro:"Utang menunda konsumsi masa depan",q:"Benar atau Salah: Berutang berarti memindahkan kemampuan belanja dari masa depan ke sekarang — nanti penghasilanmu akan terpakai untuk membayar barang yang sudah kamu nikmati.",answer:true,explain:"Utang = 'aku sekarang' meminjam dari 'aku nanti', ditambah biaya bunga. Karena itu utang hanya sepadan bila manfaatnya lebih besar dari biayanya.",hint:"Penghasilan bulan depan sebagian sudah 'terpakai' untuk apa?"},
{n:64,type:"mcq",micro:"Perangkap cicilan minimum",q:"Mengapa membayar hanya cicilan minimum kartu kredit bisa menjebak?",options:["Karena cicilan minimum hanya menutup biaya administrasi, sehingga bunga baru ditagih setelah seluruh pokok utang terbayar","Karena pembayaran minimum dihitung dari pokok saja, sehingga utang cepat lunas dalam beberapa bulan dengan total biaya kecil","Karena sebagian besar pembayaran habis untuk bunga, pokok nyaris tak berkurang, sehingga utang bertahan bertahun-tahun & total biayanya berlipat"],answer:2,explain:"Cicilan minimum dirancang agar peminjam terus berutang. Melunasi penuh atau membayar jauh di atas minimum memutus jebakan.",hint:"Kalau bayaranmu kecil, ke mana sebagian besarnya pergi: pokok atau bunga?"},
{n:65,type:"mcq",micro:"Dampak sosial gagal bayar",q:"Selain denda & agunan disita, gagal bayar sering menimbulkan...",options:["Nama masuk catatan kredit buruk (sulit pinjam KPR/usaha kelak), hubungan keluarga tegang, stres berat, & kadang masalah hukum","Skor kredit naik karena sering telat, hubungan keluarga makin akrab, dan peluang pinjaman besar kelak bertambah","Hanya kehilangan sedikit uang jajan; catatan kredit, hubungan keluarga, dan pekerjaan tidak terpengaruh"],answer:0,explain:"Akibat gagal bayar merembet jauh melewati uang: reputasi, kesehatan mental, & hubungan. Mencegah jauh lebih murah.",hint:"Apa saja yang rusak selain dompet?"},
{n:66,type:"mcq",micro:"Menilai 'butuh sekarang'",q:"Cara menguji apakah kamu benar-benar perlu berutang untuk sesuatu:",options:["Ikuti saja apa kata penjual atau penawar pinjaman, karena mereka paling tahu apa yang kamu butuhkan dan seberapa mampu kamu membayar","Tanyakan: Apakah ini kebutuhan mendesak yang tak bisa ditunda? Bisakah aku menabung dulu? Apakah cicilannya aman? Apa akibatnya bila aku tidak membelinya sekarang?","Beli saja kalau kamu menginginkannya, karena keinginan yang kuat adalah tanda bahwa barang itu memang benar-benar kamu perlukan sekarang"],answer:1,explain:"Sebagian besar 'darurat belanja' sebenarnya bisa ditunda & ditabung. Utang sejati untuk hal yang benar-benar tak bisa menunggu.",hint:"Pertanyaan apa yang memisahkan 'butuh sekarang' dari 'ingin sekarang'?"},
{n:67,type:"tf",micro:"Harga sebuah tenor panjang",q:"Benar atau Salah: Memilih tenor cicilan yang lebih panjang menekan cicilan bulanan, tetapi menambah total bunga yang dibayar & memperpanjang keterikatan pada utang.",answer:true,explain:"Karena itu pilih tenor terpendek yang cicilannya masih aman bagi anggaran, bukan sekadar yang cicilan bulanannya paling kecil.",hint:"Cicilan kecil enak, tapi apa harganya sepanjang waktu?"},
{n:68,type:"mcq",micro:"Membandingkan dua tawaran",q:"Tawaran X: bunga 12%/tahun, biaya admin Rp0. Tawaran Y: bunga 8%/tahun, tapi biaya admin & asuransi 6% dari pokok di depan. Untuk pinjaman 1 tahun, yang benar:",options:["X lebih mahal karena bunganya tampak lebih besar, jadi Y layak dipilih tanpa perlu dihitung lagi","Keduanya sama persis; bunga dan biaya di depan saling meniadakan, jadi pilih yang prosesnya lebih cepat","Y belum tentu lebih murah — biaya di depan 6% hampir menutup selisih bunga; hitung total biaya sebelum memilih"],answer:2,explain:"Bunga rendah yang 'dibungkus' biaya awal besar bisa lebih mahal. Bandingkan total rupiah yang keluar, bukan satu angka.",hint:"Jumlahkan bunga + semua biaya di masing-masing tawaran."},
{n:69,type:"mcq",micro:"Peran inflasi pada utang",q:"Bila kamu punya utang dengan cicilan tetap & penghasilanmu naik mengikuti inflasi, maka seiring waktu...",options:["Beban cicilan terasa sedikit lebih ringan relatif terhadap penghasilan","Cicilan ikut membesar mengikuti inflasi, sehingga makin lama makin berat dibayar","Jumlah utang berlipat sendiri karena inflasi, sehingga melebihi pinjaman awal"],answer:0,explain:"Utang berbunga tetap dengan cicilan tetap sedikit 'tergerus' inflasi — salah satu alasan KPR jangka panjang bisa masuk akal. Ini beda dari utang berbunga liar yang menunggak.",hint:"Kalau gaji naik tapi cicilan tetap, porsinya terhadap gaji naik atau turun?"},
{n:70,type:"order",micro:"Dari tergoda ke keputusan bijak",q:"Urutkan proses berpikir sehat saat tergoda tawaran kredit barang keinginan.",items:["Sadari dorongan ingin membeli & tunda keputusan 24 jam","Hitung total biaya kredit & bandingkan dengan harga tunai","Cek apakah cicilan muat di anggaran tanpa mengorbankan kebutuhan & tabungan","Putuskan: tabung dulu, beli versi lebih murah, atau relakan — hindari utang konsumtif"],answer:[0,1,2,3],explain:"Jeda → hitung → cek anggaran → putuskan tanpa berutang untuk keinginan. Menunda sering membuat keinginan memudar.",hint:"Langkah pertama meredam emosi; langkah terakhir mengambil keputusan."},
{n:71,type:"mcq",micro:"Kapan utang justru bijak",q:"Contoh situasi di mana berutang bisa lebih bijak daripada tidak:",options:["Kredit gawai terbaru tiap tahun demi gengsi, karena cicilan kecil membuat barang mahal terasa murah","Modal usaha kecil dengan bunga wajar yang terbukti menghasilkan arus kas jauh di atas cicilan","Pinjol baru untuk menutup utang lain berbunga tinggi, tanpa menghitung total biaya dan dendanya"],answer:1,explain:"Utang produktif dengan rencana kas yang realistis & bunga wajar bisa mempercepat perbaikan keuangan.",hint:"Utang yang menghasilkan lebih dari biayanya, atau yang hanya menghabiskan?"},
{n:72,type:"mcq",micro:"'Bunga 0%' & harga digelembungkan",q:"Sebuah barang tunai di toko lain Rp2.000.000, tapi di toko ini 'cicilan 0% 12×Rp200.000'. Kamu sebenarnya membayar...",options:["Rp2.000.000 — sama dengan harga tunai; tidak ada bunga yang disembunyikan dalam harga","Rp1.800.000 — Rp200.000 lebih murah; cicilan memberi potongan dalam harga yang diturunkan","Rp2.400.000 — Rp400.000 lebih mahal; 'bunga' disembunyikan dalam harga yang dinaikkan"],answer:2,explain:"12 × Rp200.000 = Rp2.400.000. 'Bunga 0%' tidak berarti tanpa biaya bila harga dasarnya sudah digelembungkan.",hint:"Bandingkan total cicilan dengan harga tunai di toko lain, bukan dengan klaim '0%'."},
{n:73,type:"tf",micro:"Utang keluarga tetap utang",q:"Benar atau Salah: Meminjam dari orang tua atau saudara berarti kamu tidak punya kewajiban apa pun untuk mengembalikannya.",answer:false,explain:"Sebaliknya, utang keluarga tetaplah utang. Meski sering tanpa bunga & fleksibel, tidak mengembalikannya merusak kepercayaan & hubungan yang jauh lebih berharga daripada uang.",hint:"Tidak ada bunga — tapi apakah kepercayaan juga 'gratis'?"},
{n:74,type:"mcq",micro:"Sinyal keuangan tidak sehat",q:"Tanda seseorang mulai terjebak utang:",options:["Berutang untuk kebutuhan harian, membayar utang dengan utang baru, hanya sanggup cicilan minimum, & menyembunyikan tagihan dari keluarga","Melunasi cicilan lebih cepat dari jadwal yang ditentukan dan mengurangi pokok utang setiap bulan secara teratur","Punya dana darurat yang cukup dan menabung secara rutin, sambil membayar cicilan tepat waktu tanpa harus berutang lagi"],answer:0,explain:"Pola-pola ini menunjukkan pengeluaran melebihi kemampuan. Semakin cepat dikenali & dihadapi, semakin ringan pemulihannya.",hint:"Perilaku mana yang menunjukkan lubang makin dalam?"},
{n:75,type:"mcq",micro:"Bunga harian pinjol",q:"'Bunga 0,5% per hari' terdengar kecil, tetapi setara dengan sekitar...",options:["Tidak bisa dibandingkan karena periodenya berbeda","15% per bulan / 180% per tahun — sangat mahal","1,5% per bulan / 18% per tahun — cukup murah"],answer:1,explain:"0,5% × 30 hari = 15% sebulan; × 12 ≈ 180% setahun (lebih tinggi lagi bila berbunga majemuk). Bunga harian menyamarkan biaya sesungguhnya.",hint:"Kalikan bunga harian dengan 30, lalu dengan 12."},
{n:76,type:"mcq",micro:"Trade-off menabung vs melunasi",q:"Kamu punya sedikit uang lebih. Biasanya paling menguntungkan...",options:["Menaruhnya di investasi berisiko tinggi, karena potensi untung yang besar biasanya mengalahkan bunga utang yang sedang berjalan, lalu utangnya dilunasi nanti dari hasilnya","Menyimpannya di laci tanpa tujuan jelas supaya mudah diambil bila ada barang yang ingin dibeli mendadak, sambil utang berjalan terus","Melunasi/mengurangi utang berbunga tinggi lebih dulu, karena 'imbal hasil'-nya = bunga yang tidak jadi dibayar, sering lebih besar dari bunga tabungan"],answer:2,explain:"Menghapus utang berbunga 20% ibarat mendapat 'keuntungan pasti 20%'. Sisakan dana darurat kecil, lalu serang utang termahal.",hint:"Bunga utang yang kamu hindari vs bunga tabungan yang kamu dapat — mana lebih besar?"},
{n:77,type:"tf",micro:"Membaca syarat itu penting",q:"Benar atau Salah: Bagian 'syarat & ketentuan' serta rincian denda pada perjanjian pinjaman sering memuat biaya penting, sehingga wajib dibaca sebelum setuju.",answer:true,explain:"Banyak kerugian peminjam berasal dari klausul yang tidak dibaca: denda besar, bunga berjalan, penalti pelunasan, atau kuasa menyita.",hint:"Di mana biasanya 'kejutan biaya' disembunyikan?"},
{n:78,type:"mcq",micro:"Efek utang pada pilihan hidup",q:"Beban utang yang besar dapat membatasi seseorang karena...",options:["Sebagian penghasilan masa depan sudah 'terkunci' untuk cicilan, mengurangi kebebasan berganti pekerjaan, menabung, atau menghadapi keadaan darurat","Membuat seseorang lebih bebas secara finansial, karena uang pinjaman memberi banyak pilihan dan kebebasan di masa depan tidak berkurang","Tidak memengaruhi pilihan hidup, sebab cicilan hanya angka kecil yang mudah diabaikan saat memilih pekerjaan, menabung, atau berhadapan dengan keadaan darurat"],answer:0,explain:"Utang menukar fleksibilitas masa depan dengan barang hari ini. Utang seperlunya menjaga ruang gerak keuanganmu.",hint:"Kalau gaji sudah 'dipesan' cicilan, seberapa bebas kamu mengambil risiko baik?"},
{n:79,type:"mcq",micro:"Menilai iklan 'ringan'",q:"Iklan kredit menonjolkan 'DP 0%! Angsuran mulai Rp99.000!' Yang sebaiknya kamu tanyakan:",options:["Apakah toko memberi hadiah gantungan kunci atau barang tambahan lain, karena itu menentukan apakah tawaran kredit layak diambil","Berapa total semua angsuran, berapa lama tenornya, berapa bunga per tahun, biaya apa saja yang ada, & berapa denda telat","Di mana lokasi toko penyedia kredit dan bagaimana tampilannya, karena toko yang bagus dan dekat menawarkan cicilan termurah"],answer:1,explain:"Iklan menyorot angka terkecil. Keputusan sehat butuh angka total & semua biaya, bukan potongan yang paling menarik.",hint:"Angka mana yang sengaja tidak ditonjolkan iklan?"},
{n:80,type:"open",micro:"Menjelaskan bunga ke teman",q:"Temanmu berkata, 'Beli kredit sama saja dengan tunai, kan tinggal bayar tiap bulan.' Jelaskan dengan satu contoh angka mengapa anggapan itu keliru, dan kapan kredit tetap bisa dipertimbangkan.",explain:"Jawaban baik menunjukkan selisih angka konkret (mis. Rp1.200.000 vs Rp1.000.000 = bunga Rp200.000), menegaskan kredit umumnya lebih mahal, lalu menyebut syarat wajar mempertimbangkan kredit (butuh mendesak, cicilan aman, bunga wajar/resmi, atau produktif).",hint:"Kalikan cicilan × jumlah bulan, bandingkan dengan harga tunai, lalu sebut kapan selisih itu masih layak dibayar.",sample:"Contoh: sepeda Rp1.000.000 tunai, atau kredit Rp100.000 × 12 = Rp1.200.000. Berarti membeli kredit membuatmu membayar Rp200.000 lebih mahal — itu biaya bunga, imbalan untuk pemberi pinjaman karena kamu 'memiliki sekarang, bayar nanti'. Jadi kredit hampir selalu lebih mahal daripada tunai, bukan 'sama saja'. Kredit tetap bisa dipertimbangkan bila: barangnya benar-benar dibutuhkan sekarang dan tak bisa ditunda, cicilannya kecil dan aman di anggaran, bunganya wajar dari lembaga resmi, atau barang itu justru membantu menghasilkan uang lebih besar dari cicilannya (misalnya alat kerja). Untuk keinginan atau gaya hidup, lebih baik menabung dulu."},
{n:81,type:"mcq",micro:"Kasus: dua kredit motor",q:"Motor Rp18.000.000. Opsi A: DP Rp3.000.000 + Rp850.000 × 24. Opsi B: DP Rp5.000.000 + Rp700.000 × 24. Total biaya A vs B:",options:["A = Rp21.800.000; B = Rp23.400.000 — A lebih murah Rp1.600.000 karena DP-nya kecil & cicilan ringan","A dan B sama-sama Rp22.600.000 — keduanya sama saja karena DP dan pokoknya saling menyeimbangkan","A = Rp23.400.000; B = Rp21.800.000 — B lebih murah Rp1.600.000 karena DP lebih besar & pokok lebih kecil"],answer:2,explain:"A: 3jt + (850rb×24=20,4jt) = 23,4jt. B: 5jt + (700rb×24=16,8jt) = 21,8jt. DP besar menekan total bunga.",hint:"Hitung DP + (cicilan × 24) untuk masing-masing."},
{n:82,type:"mcq",micro:"Kasus: pinjol berantai",q:"Seseorang meminjam di pinjol A untuk bayar pinjol B, lalu pinjam di C untuk bayar A. Setelah beberapa putaran, kemungkinan besar total utangnya...",options:["Membesar terus karena tiap pinjaman baru menambah bunga & biaya, sampai tak tertahankan","Mengecil bertahap karena rajin membayar cicilan, sehingga bunga baru berhenti bertambah","Tetap sama karena tiap pinjaman baru hanya menggantikan pinjaman lama dengan jumlah setara"],answer:0,explain:"'Gali lubang tutup lubang' menambah beban di tiap langkah. Jalan keluarnya: berhenti berutang baru, hadapi, negosiasi, cari bantuan resmi.",hint:"Setiap pinjaman baru menambah apa ke total utang?"},
{n:83,type:"tf",micro:"Refleksi: menunda bukan gagal",q:"Benar atau Salah: Memutuskan menabung dulu selama setahun daripada mengkredit sebuah barang keinginan adalah bentuk kegagalan finansial.",answer:false,explain:"Sebaliknya, menunda pembelian sampai mampu membayar tunai adalah tanda disiplin keuangan yang kuat — kamu menghindari bunga & memegang kendali, bukan gagal.",hint:"Sabar menabung: kelemahan atau kekuatan?"},
{n:84,type:"mcq",micro:"Kasus: tawaran 'konsolidasi'",q:"Sebuah lembaga menawarkan menggabungkan semua utangmu jadi satu cicilan 'lebih ringan' selama tenor 2× lebih panjang. Sebelum setuju, kamu harus memastikan...",options:["Lembaganya berkantor megah dan petugasnya ramah menjelaskan, karena kesan baik itu menunjukkan tawarannya aman dan murah","Total seluruh biaya (bunga + admin) sepanjang tenor baru benar-benar lebih kecil, bukan sekadar cicilan bulanan yang terlihat ringan","Cicilan bulanannya lebih kecil saja, sebab cicilan kecil berarti total biaya yang dibayar peminjam juga lebih hemat"],answer:1,explain:"Konsolidasi bisa membantu bila menurunkan total biaya & bunga; berbahaya bila hanya memperpanjang penderitaan dengan total lebih besar.",hint:"Cicilan ringan + tenor 2× panjang sering berarti total bunga lebih...?"},
{n:85,type:"order",micro:"Membangun ketahanan agar tak berutang",q:"Urutkan langkah membangun keuangan yang tahan guncangan sehingga tidak perlu berutang darurat.",items:["Buat anggaran: belanja lebih kecil dari penghasilan","Bangun dana darurat bertahap (mis. 3-6 bulan biaya hidup)","Lunasi utang berbunga tinggi yang ada","Mulai menabung & berinvestasi untuk tujuan jangka panjang"],answer:[0,1,2,3],explain:"Anggaran surplus → dana darurat → hapus utang mahal → menabung/investasi. Fondasi ini memutus kebutuhan berutang saat krisis.",hint:"Apa fondasi paling dasar sebelum bisa menabung dana darurat?"},
{n:86,type:"mcq",micro:"Kasus: agunan sertifikat rumah",q:"Ayah ingin menggadaikan sertifikat rumah untuk modal usaha yang belum teruji sama sekali. Risiko terbesarnya:",options:["Risiko kecil karena rumah tetap boleh ditinggali selama cicilan dibayar, jadi usaha yang belum teruji pun aman dimodali","Bunga otomatis jadi nol karena ada jaminan sertifikat rumah, sehingga biaya pinjaman jauh lebih murah dan aman","Bila usaha gagal & cicilan macet, rumah keluarga bisa disita — kehilangan tempat tinggal, bukan sekadar uang"],answer:2,explain:"Menjaminkan aset penting untuk rencana yang belum terbukti sangat berisiko. Uji usaha skala kecil dulu sebelum mempertaruhkan rumah.",hint:"Apa yang hilang kalau agunan berupa rumah lalu terjadi gagal bayar?"},
{n:87,type:"mcq",micro:"Kasus: teman menagih utang lama",q:"Kamu berutang Rp200.000 ke teman 6 bulan lalu & lupa. Ia menagih dengan sungkan. Respons terbaik:",options:["Minta maaf atas keterlambatan, segera bayar penuh (atau sepakati tanggal pasti bila belum ada dananya), & catat agar tak terulang","Marah karena merasa ditagih padahal kamu masih ingin menunda, lalu menjelaskan bahwa temanmu seharusnya bersabar dan tidak mendesak","Pura-pura tidak ingat dan mengalihkan pembicaraan ke hal lain, berharap temanmu merasa sungkan lalu tidak menagih lagi di kemudian hari"],answer:0,explain:"Utang yang diakui & dibayar menjaga persahabatan. Menghindar atau menyalahkan penagih justru merusaknya.",hint:"Apa yang menjaga hubungan: tanggung jawab atau pembelaan diri?"},
{n:88,type:"tf",micro:"Semua utang itu buruk?",q:"Benar atau Salah: Semua bentuk utang selalu buruk & harus dihindari dalam segala keadaan.",answer:false,explain:"Sebaliknya, utang adalah alat: berbahaya untuk keinginan/gaya hidup dengan bunga tinggi, tetapi bisa masuk akal untuk kebutuhan penting atau tujuan produktif bila bunganya wajar & cicilannya terjangkau.",hint:"Alat yang sama bisa berguna atau berbahaya tergantung...?"},
{n:89,type:"mcq",micro:"Kasus: bonus untuk utang",q:"Seseorang menerima bonus Rp5.000.000. Ia punya utang kartu kredit Rp4.000.000 (bunga sangat tinggi) & belum punya dana darurat. Langkah paling bijak umumnya:",options:["Taruh semuanya di investasi berisiko tinggi, karena potensi untung besar bisa membayar kartu kredit sekaligus dana darurat","Sisihkan dana darurat kecil (mis. Rp1.000.000), lalu pakai Rp4.000.000 untuk melunasi kartu kredit berbunga tinggi","Belanjakan seluruhnya untuk hadiah diri karena bonus pantas dinikmati, sedangkan utang kartu kredit dicicil seperti biasa"],answer:1,explain:"Melunasi utang berbunga sangat tinggi memberi 'imbal hasil' setara bunga tersebut, hampir pasti lebih baik daripada pilihan lain. Sisakan sedikit penyangga tunai.",hint:"Mana yang paling 'mahal' bila dibiarkan: utang kartu kredit atau kehilangan kesempatan investasi?"},
{n:90,type:"open",micro:"Analisis keputusan KPR sederhana",q:"Sebuah keluarga mempertimbangkan KPR rumah: harga Rp400 juta, DP Rp80 juta, cicilan Rp3.500.000/bulan selama 15 tahun. Penghasilan bersih keluarga Rp12.000.000/bulan, belum ada utang lain. Bahas: (1) apakah cicilan masuk akal terhadap penghasilan, (2) kira-kira total yang dibayar & biaya bunganya, (3) faktor risiko yang harus disiapkan, (4) kesimpulan.",explain:"Jawaban baik menghitung rasio cicilan (~29%), memperkirakan total bayar (~Rp710 juta) & biaya bunga (~Rp310 juta), menyebut risiko (penghasilan, bunga mengambang, biaya rumah, perlu dana darurat), lalu menyimpulkan secara berimbang bahwa KPR bisa masuk akal sebagai utang produktif/kebutuhan bila fondasi keuangannya kuat.",hint:"Bagi cicilan dengan penghasilan; kalikan cicilan × 12 × tahun lalu tambah DP; pikirkan apa yang bisa membuat pembayaran gagal.",sample:"(1) Cicilan Rp3.500.000 ÷ Rp12.000.000 ≈ 29% dari penghasilan, masih di sekitar batas pedoman ~30%, jadi relatif masuk akal selama pengeluaran lain terkendali. (2) Total cicilan = Rp3.500.000 × 12 × 15 = Rp630.000.000, ditambah DP Rp80.000.000 = Rp710.000.000. Dibanding harga Rp400.000.000, biaya bunga & terkait sekitar Rp310.000.000 selama 15 tahun — sangat besar, meski rumah biasanya naik nilainya & memberi tempat tinggal. (3) Risiko yang harus disiapkan: kehilangan/penurunan penghasilan, suku bunga mengambang yang bisa naik, biaya perawatan rumah, pajak & asuransi, serta perlunya dana darurat 6-12 bulan cicilan. (4) Kesimpulan: KPR ini layak dipertimbangkan karena rasio cicilan sehat, tujuannya kebutuhan jangka panjang (tempat tinggal) dan berpotensi menjadi aset, asalkan keluarga punya dana darurat kuat, memahami risiko bunga naik, dan tetap bisa menabung untuk tujuan lain."},
{n:91,type:"mcq",micro:"Kasus: 'paylater' impulsif",q:"Fitur 'bayar nanti' (paylater) di aplikasi belanja membuat orang mudah berutang karena...",options:["Membuat tagihan terasa lebih berat sehingga belanja berkurang, dan tidak ada risiko tagihan menumpuk walau pembayaran terlambat berbulan-bulan","Memberi uang tambahan gratis kepada pengguna yang sering berbelanja, sehingga makin banyak berutang makin besar keuntungan pengguna","Menghilangkan 'rasa sakit membayar' saat itu juga, sehingga belanja impulsif meningkat & tagihan menumpuk dengan bunga/denda bila telat"],answer:2,explain:"Paylater mengubah banyak keinginan kecil menjadi tumpukan utang. Perlakukan seperti kartu kredit: pakai sangat selektif & lunasi penuh tepat waktu.",hint:"Kalau membayar terasa 'nanti saja', apa yang terjadi pada dorongan belanja?"},
{n:92,type:"tf",micro:"Bunga majemuk dua arah",q:"Benar atau Salah: Bunga majemuk bisa menjadi sahabat terbaik (saat menabung/berinvestasi) sekaligus musuh terberat (saat berutang & menunggak).",answer:true,explain:"Mesin yang sama bekerja untukmu bila kamu pemilik aset, dan melawanmu bila kamu peminjam yang menunggak. Maka: tabung lebih awal, dan jangan biarkan utang berbunga menumpuk.",hint:"Siapa yang diuntungkan bunga berbunga: pemilik uang atau peminjam yang telat?"},
{n:93,type:"mcq",micro:"Kasus: pilih tenor",q:"Kredit Rp12.000.000. Tenor 12 bulan: cicilan Rp1.150.000 (total Rp13.800.000). Tenor 24 bulan: cicilan Rp650.000 (total Rp15.600.000). Sisa anggaran cicilan Rp1.300.000/bulan. Pilihan lebih hemat & tetap aman:",options:["Tenor 12 bulan — cicilan Rp1.150.000 masih muat, & menghemat Rp1.800.000 bunga dibanding tenor 24 bulan","Tenor 24 bulan — cicilan lebih kecil sehingga lebih ringan, & bunga totalnya lebih rendah daripada tenor 12 bulan","Tidak memilih keduanya — kebutuhan itu ditunda karena cicilan tenor 12 maupun 24 bulan sama-sama terlalu berat"],answer:0,explain:"Bila cicilan tenor pendek masih aman di anggaran, memilihnya memangkas total bunga secara signifikan.",hint:"Cicilan mana yang muat, dan berapa selisih total kedua opsi?"},
{n:94,type:"mcq",micro:"Kasus: ditawari utang saat sedih",q:"Setelah kehilangan pekerjaan, seseorang ditawari pinjaman cepat 'untuk menyambung hidup'. Sikap paling bijak:",options:["Ambil dari beberapa aplikasi pinjol sekaligus supaya uangnya cukup banyak, lalu cari pekerjaan baru setelah semua kebutuhan terpenuhi","Utamakan memangkas pengeluaran drastis, gunakan dana darurat, cari bantuan keluarga/jaring pengaman, & cari kerja; utang berbunga saat tanpa penghasilan sangat berbahaya","Ambil pinjaman sebesar-besarnya selagi masih disetujui, karena kesempatan seperti itu belum tentu datang lagi saat keadaan makin sulit setiap saat"],answer:1,explain:"Berutang tanpa sumber pembayaran yang jelas mempercepat krisis. Utang darurat adalah pilihan paling akhir & sekecil mungkin.",hint:"Kalau belum ada penghasilan, dari mana cicilan akan dibayar?"},
{n:95,type:"tf",micro:"Melunasi utang mahal lebih cepat",q:"Benar atau Salah: Untuk utang berbunga tinggi, melunasi lebih cepat umumnya menguntungkan karena menghentikan bunga berjalan — sepanjang tidak ada penalti pelunasan & dana darurat tetap aman.",answer:true,explain:"Bunga yang tak jadi dibayar adalah 'keuntungan pasti'. Cek dulu klausul penalti & sisakan penyangga tunai sebelum mempercepat pelunasan.",hint:"Bunga yang tak jadi kamu bayar itu keuntungan atau kerugian?"},
{n:96,type:"mcq",micro:"Kasus: teman minta jadi penjamin pinjol",q:"Teman memintamu 'hanya meminjamkan namamu' untuk mendaftar pinjol karena namanya sudah masuk daftar hitam. Ini...",options:["Boleh saja karena kamu hanya 'meminjamkan nama' dan bukan uang, sehingga tidak menanggung utang atau denda","Wajib dibantu demi pertemanan, karena menolak teman yang kesulitan adalah tindakan buruk yang merusak persahabatan","Sangat berbahaya & bisa jadi penipuan: kamu yang akan menanggung seluruh utang, denda, & teror penagihan; tegas menolak"],answer:2,explain:"'Meminjamkan nama' berarti kamu peminjam resminya. Semua akibat hukum & keuangan jatuh padamu. Tolak tanpa ragu.",hint:"Siapa yang tercatat sebagai peminjam & ditagih bila cicilan macet?"},
{n:97,type:"mcq",micro:"Prinsip inti bab ini",q:"Pesan inti tentang pinjaman, bunga, & risiko:",options:["Utang adalah alat berbiaya (bunga) & berisiko: pakai seminimal mungkin, hanya untuk hal penting/produktif dengan bunga wajar & cicilan terjangkau, bayar tepat waktu, dan hindari rentenir/pinjol ilegal serta utang konsumtif","Berutang sebanyak yang disetujui pemberi pinjaman, karena bunga hanya angka kecil dan utang konsumtif jarang menimbulkan masalah di kemudian hari; yang penting cicilan dibayar belakangan jika uangnya sudah ada","Semua utang gratis asalkan dicicil tepat waktu, sehingga bunga, denda, dan pihak pemberi pinjaman tidak perlu dicek; yang penting persetujuan cepat dan prosesnya mudah, termasuk dari aplikasi tanpa izin resmi"],answer:0,explain:"Ringkasan: pahami total biaya, jaga cicilan sehat, prioritaskan tujuan penting/produktif, bayar tepat waktu, jauhi pemberi pinjaman predator.",hint:"Alat, biaya, risiko, tepat waktu, hindari predator — rangkai jadi satu kalimat."},
{n:98,type:"tf",micro:"Tepat waktu itu strategi termurah",q:"Benar atau Salah: Membayar setiap cicilan tepat waktu adalah salah satu cara paling sederhana & murah untuk menekan biaya utang serta menjaga reputasi kredit.",answer:true,explain:"Tepat waktu menghindari denda, bunga berjalan, & catatan buruk. Aturkan pengingat atau autodebet dari rekening yang selalu cukup saldo.",hint:"Apa akibat termurah: bayar tepat waktu, atau kena denda + bunga + catatan buruk?"},
{n:99,type:"mcq",micro:"Kasus: memilih tidak berutang",q:"Sebuah keluarga memutuskan menunda membeli mobil 3 tahun & menabung, alih-alih kredit berbunga besar sekarang. Kemungkinan hasilnya:",options:["Tetap membeli mobil lebih lama, sehingga selama menabung kamu rugi karena kesempatan itu hilang dan tidak bisa dikejar kembali","Membeli tunai kelak dengan harga penuh tanpa bunga, keuangan bulanan lebih lega selama menabung, & terbiasa hidup di bawah kemampuan","Membeli kredit kelak dengan bunga lebih rendah, keuangan bulanan lebih berat selama menabung, & terbiasa hidup melebihi kemampuan"],answer:1,explain:"Menabung untuk membeli tunai menukar 'menunggu' dengan 'menghemat bunga & menjaga fleksibilitas'. Sering kali ini keputusan paling menguntungkan.",hint:"Apa yang didapat dengan bersabar menabung dibanding mengkredit?"},
{n:100,type:"open",micro:"Refleksi & aturan pribadi utang",q:"Tulis 'aturan pribadi tentang utang' berisi minimal 5 poin yang akan kamu pegang saat dewasa nanti, masing-masing dengan alasan singkat.",explain:"Jawaban baik memuat minimal 5 aturan konkret dengan alasan, mencakup ide-ide inti bab: hindari utang konsumtif, hitung total biaya, jaga rasio cicilan sehat, hanya sumber resmi, bayar tepat waktu, punya dana darurat, jangan menjamin utang orang lain, dan batasi utang untuk tujuan penting/produktif.",hint:"Ambil satu pelajaran dari tiap fase — konsumtif vs produktif, hitung biaya, rasio cicilan, sumber aman, tepat waktu, dana darurat — dan ubah jadi aturan 'aku akan...'.",sample:"Contoh aturan pribadi: (1) Tidak berutang untuk keinginan atau gaya hidup (baju, gawai tren, liburan) — nilainya cepat pudar, bunganya tidak; aku menabung dulu. (2) Sebelum berutang, aku hitung total biaya (pokok + semua bunga + biaya) dan bandingkan dengan harga tunai — supaya tahu harga sebenarnya. (3) Total semua cicilanku tidak melebihi 30% penghasilan bersih — agar satu kejutan hidup tidak membuatku gagal bayar. (4) Aku hanya meminjam dari lembaga resmi yang diawasi; tidak pernah dari rentenir atau pinjol ilegal — karena bunga liar & penagihan kasar menjebak. (5) Aku bayar setiap cicilan tepat waktu, kalau bisa lebih cepat — untuk menghentikan bunga & menjaga reputasi kredit. (6) Aku bangun dana darurat 3-6 bulan biaya hidup sebelum membeli barang besar — supaya darurat tidak memaksaku berutang. (7) Aku tidak menjadi penjamin atau 'meminjamkan nama' untuk utang orang lain — karena risikonya jatuh penuh padaku. (8) Utang hanya kupertimbangkan untuk hal penting jangka panjang atau produktif (pendidikan, rumah, modal usaha teruji) dengan bunga wajar."},
];
